//! Original generative score, field patches and vowel blips, shared by live and offline output.
use crate::{Patch,Wave,Mixer};
use pav_core::games::merc::Merc;
#[derive(Clone,Copy,Debug)]pub enum Bus{Music,Sfx,Voice}
#[derive(Clone,Debug)]pub struct Cue{pub patch:Patch,pub bus:Bus,pub pan:f32,pub gain:f32,pub delay:f32}
impl Cue{fn new(patch:Patch,bus:Bus,gain:f32,delay:f32)->Self{Self{patch,bus,pan:0.,gain,delay}}}
pub fn weapon(family:u8)->Vec<Cue>{let mut n=Patch::new(Wave::Noise,80.+family as f32*70.);n.decay=0.06+family as f32*0.018;n.release=0.1;n.cutoff=4200.-family as f32*500.;n.cutoff_end=300.;n.volume=0.4;let mut b=Patch::new(Wave::Sine,95.-family as f32*7.);b.freq_end=35.;b.glide=0.1;b.decay=0.14;b.release=0.03;b.volume=0.5;vec![Cue::new(n,Bus::Sfx,1.,0.),Cue::new(b,Bus::Sfx,1.,0.)]}
pub fn voice(speaker:&str,text:&str,tape:bool)->Vec<Cue>{let h=speaker.bytes().fold(0u32,|a,b|a.wrapping_mul(31).wrapping_add(b as u32));let base=135.+(h%110) as f32;let mut cues=Vec::new();for (i,ch) in text.chars().filter(|c|c.is_alphabetic()).step_by(3).take(24).enumerate(){let code=ch as u32;let mut p=Patch::new(Wave::Saw,base*(1.+((code%7) as f32-3.)*0.045));p.freq_end=p.freq*if i%3==0{1.12}else{0.92};p.glide=0.08;p.attack=0.012;p.decay=0.03;p.sustain=0.4;p.hold=0.025;p.release=0.03;p.volume=0.18;p.cutoff=if tape{1300.}else{700.+(code%5) as f32*400.};p.cutoff_end=500.;cues.push(Cue::new(p,Bus::Voice,1.,i as f32*0.075));}cues}
pub fn effect(kind:u8)->Vec<Cue>{if (20..25).contains(&kind){return weapon(kind-20);}let mut p=Patch::new(if matches!(kind,0|1|3|33){Wave::Sine}else{Wave::Noise},match kind{0=>750.,1=>190.,3=>520.,33=>950.,_=>110.});p.decay=if kind==30{0.65}else{0.08};p.release=if kind==30{0.5}else{0.06};p.cutoff=if kind==30{600.}else{2200.};p.cutoff_end=120.;p.volume=if kind==0{0.08}else{0.28};if kind==30{p.freq=45.;p.freq_end=18.;}vec![Cue::new(p,Bus::Sfx,1.,0.)]}
#[derive(Default)]pub struct Score{pub clock:f32,pub beat:u64,pub voice_serial:u32,pub sound_serial:u32,pub since_step:f32}
impl Score{pub fn update(&mut self,g:&Merc,dt:f32)->Vec<Cue>{let mut out=Vec::new();if g.finished{return out;}self.clock-=dt;if self.clock<=0.{self.clock+=0.4;self.beat+=1;let combat=g.soldiers.iter().any(|n|n.state==2&&n.hp>0.&&pav_core::games::merc::data::distance(n.pos,g.pos)<80.);let notes=[0,7,10,3,7,0,5,10,12,7,3,5];let n=notes[self.beat as usize%notes.len()];let mut p=Patch::new(Wave::Pluck,110.*2f32.powf(n as f32/12.));p.decay=0.8;p.release=0.2;p.volume=0.35;p.cutoff=3000.;out.push(Cue::new(p,Bus::Music,1.,0.));if self.beat%4==0{let mut drum=Patch::new(Wave::Sine,85.);drum.freq_end=28.;drum.glide=0.09;drum.decay=0.15;drum.volume=0.25;out.push(Cue::new(drum,Bus::Music,1.,0.));}if combat{let mut guitar=Patch::new(Wave::Saw,55.*2f32.powf(n as f32/12.));guitar.decay=0.3;guitar.volume=0.1;guitar.cutoff=500.;out.push(Cue::new(guitar,Bus::Music,1.,0.));}
 let mut wind=Patch::new(Wave::Noise,100.);wind.attack=0.06;wind.decay=0.4;wind.release=0.15;wind.volume=0.06*(g.wind_speed/12.);wind.cutoff=500.;wind.cutoff_end=300.;out.push(Cue::new(wind,Bus::Sfx,1.,0.));let fire_count=g.fire.cells.iter().filter(|&(&(x,z),c)|c.state==1&&glam::Vec2::new(x as f32*2.,z as f32*2.).distance(pav_core::games::merc::data::flat(g.pos))<50.).count();if fire_count>0{let mut fire=Patch::new(Wave::Noise,50.);fire.attack=0.01;fire.decay=0.35;fire.release=0.15;fire.volume=(fire_count as f32/100.).sqrt().min(1.)*0.28;fire.cutoff=1200.;fire.cutoff_end=800.;out.push(Cue::new(fire,Bus::Sfx,1.,0.));}if let Some(i)=g.riding{let v=&g.vehicles[i];let mut engine=Patch::new(Wave::Saw,30.+v.speed.abs()*3.);engine.decay=0.4;engine.release=0.1;engine.volume=0.13;engine.cutoff=350.;out.push(Cue::new(engine,Bus::Sfx,1.,0.));}if g.health<20.{let mut heart=Patch::new(Wave::Sine,48.);heart.decay=0.15;heart.volume=0.20;out.push(Cue::new(heart,Bus::Sfx,1.,0.));}if g.fever_state>0{let mut ring=Patch::new(Wave::Sine,2800.);ring.decay=0.4;ring.volume=0.025;out.push(Cue::new(ring,Bus::Sfx,1.,0.));}}
 if g.sound_serial!=self.sound_serial{self.sound_serial=g.sound_serial;out.extend(effect(g.sound_kind));}if g.voice_serial!=self.voice_serial{self.voice_serial=g.voice_serial;out.extend(voice(&g.speaker,&g.subtitle,g.playing_tape.is_some()));}
 self.since_step+=dt;if g.speed>1.&&self.since_step>0.5 {self.since_step=0.;let mut step=Patch::new(Wave::Noise,100.);step.decay=0.04;step.release=0.03;step.volume=0.1;step.cutoff=850.;out.push(Cue::new(step,Bus::Sfx,1.,0.));}out}}
pub fn gain(g:&Merc,b:Bus)->f32{match b{Bus::Music=>g.settings.music*if g.subtitle_time>0.{0.45}else{1.},Bus::Sfx=>g.settings.sfx,Bus::Voice=>g.settings.voices}}
pub fn render(cues:&[Cue],seconds:f32,bus_gain:f32)->Vec<f32>{let mut m=Mixer::new(24000.);m.master=0.8;for c in cues{m.play(c.patch,c.pan,c.gain*bus_gain,c.delay);}let mut out=vec![0.;(seconds*24000.) as usize*2];m.render(&mut out);out}
